<?php
namespace EventFlow\Tests\Unit\Infrastructure\Import;
use EventFlow\Application\Import\{ImportException,UploadedFile};use EventFlow\Infrastructure\Import\{HardenedImportUploadGuard,UploadedFileRuntime};use PHPUnit\Framework\TestCase;
final class HardenedImportUploadGuardTest extends TestCase
{public function testVerifiedUploadUsesRandomExtensionPreservingPathAndDeletesAfterCallback():void{$runtime=new UploadRuntime();$guard=new HardenedImportUploadGuard($runtime);$result=$guard->withTrustedUpload(new UploadedFile('Guest List.csv','client-controlled.tmp',120,UPLOAD_ERR_OK),function(string$path,string$name)use($runtime):string{self::assertSame('random-server-path.csv',$path);self::assertSame('Guest List.csv',$name);self::assertTrue($runtime->moved);return'ok';});self::assertSame('ok',$result);self::assertSame(['random-server-path.csv'],$runtime->deleted);}public function testProvenanceSizeMimeAndFilenameFailuresAreRejectedBeforeMove():void{foreach([['uploaded'=>false],['size'=>0],['size'=>121],['mime'=>'application/x-php'],['file'=>new UploadedFile('../guests.csv','client-controlled.tmp',120,0)],['file'=>new UploadedFile('guests.exe','client-controlled.tmp',120,0)],['file'=>new UploadedFile('guests.csv','client-controlled.tmp',120,UPLOAD_ERR_PARTIAL)]]as$options){$runtime=new UploadRuntime($options);$file=$options['file']??new UploadedFile('guests.csv','client-controlled.tmp',120,0);try{(new HardenedImportUploadGuard($runtime))->withTrustedUpload($file,fn()=>null);self::fail('Expected upload rejection.');}catch(ImportException$e){self::assertSame('import_upload_invalid',$e->safeCode);self::assertFalse($runtime->moved);}}}}
final class UploadRuntime implements UploadedFileRuntime
{public bool$moved=false;public array$deleted=[];private array$options;public function __construct(array$options=[]){$this->options=$options;}public function isUploaded(string$p):bool{return$this->options['uploaded']??true;}public function size(string$p):?int{return$this->options['size']??120;}public function mime(string$p):?string{return$this->options['mime']??'text/csv';}public function temporaryPath(string$extension):string{return'random-server-path.'.$extension;}public function move(string$f,string$t):bool{$this->moved=true;return$this->options['move']??true;}public function delete(string$p):void{$this->deleted[]=$p;}}
